import openpyxl, datetime as dt, collections, json
P=lambda s: dt.datetime.strptime(s,"%m/%d/%Y").date() if s and s not in("N/A",) else None
wb=openpyxl.load_workbook("documents/employee-roster-060125.xlsx"); ws=wb["Employee Roster"]
roster=[]
for r in ws.iter_rows(min_row=2,values_only=True):
    if r[0] and str(r[0]).startswith("GRN"): roster.append(dict(id=r[0],name=r[1],title=r[2],dept=r[3],loc=r[4],hire=P(r[5]),status=r[6]))
print("roster rows",len(roster), collections.Counter(x["loc"] for x in roster), collections.Counter(x["status"] for x in roster))
ids=collections.Counter(x["id"] for x in roster); print("dup roster ids",[k for k,v in ids.items() if v>1])
nm=collections.Counter(x["name"] for x in roster); print("dup roster names",[k for k,v in nm.items() if v>1])
wb2=openpyxl.load_workbook("documents/i9-record-log.xlsx"); ws2=wb2["I-9 Record Log"]
log=[]
for r in ws2.iter_rows(min_row=2,values_only=True):
    if r[1] and str(r[1]).startswith("GRN"): log.append(dict(name=r[0],id=r[1],s1=P(r[2]),s2=P(r[3]),docs=r[4],exp=r[5],rev=r[6],revdoc=r[7],notes=r[8]))
print("log rows",len(log)); lid=collections.Counter(x["id"] for x in log); print("dup log ids",[k for k,v in lid.items() if v>1])
print("reverif rows",sum(1 for x in log if x["rev"]))
term=[x for x in log if x["notes"] and "Terminated" in x["notes"]]; print("terminated noted",len(term))
rid={x["id"]:x for x in roster}; rnm={x["name"]:x for x in roster}
lnm={x["name"]:x for x in log}
cat=collections.defaultdict(list)
for x in roster:
    l=[y for y in log if y["id"]==x["id"]]; ln=lnm.get(x["name"])
    if l and l[0]["name"]==x["name"]: cat["exact"].append(x["id"])
    elif l and ln: cat["id_other_name_and_name_elsewhere"].append((x["id"],x["name"],l[0]["name"],ln["id"]))
    elif l: cat["id_match_name_mismatch"].append((x["id"],x["name"],str(x["hire"]),l[0]["name"],str(l[0]["s1"])))
    elif ln: cat["name_match_id_mismatch"].append((x["id"],x["name"],str(x["hire"]),ln["id"],str(ln["s1"])))
    else: cat["no_record"].append((x["id"],x["name"],str(x["hire"]),x["loc"]))
for k,v in cat.items():
    print("==",k,len(v))
    for i in v: print("  ",i)
print("== log not on roster by id")
for y in log:
    if y["id"] not in rid: print("  ",y["id"],y["name"],y["s1"],y["notes"])
