import datetime as dt
def nth(y,m,wd,n):
    d=dt.date(y,m,1); c=0
    while True:
        if d.weekday()==wd:
            c+=1
            if c==n: return d
        d+=dt.timedelta(1)
def last(y,m,wd):
    d=dt.date(y,m+1,1)-dt.timedelta(1) if m<12 else dt.date(y,12,31)
    while d.weekday()!=wd: d-=dt.timedelta(1)
    return d
def obs(d):
    return d+dt.timedelta(1) if d.weekday()==6 else d-dt.timedelta(1) if d.weekday()==5 else d
def hol(y):
    h={obs(dt.date(y,1,1)),nth(y,1,0,3),nth(y,2,0,3),last(y,5,0),obs(dt.date(y,7,4)),nth(y,9,0,1),nth(y,10,0,2),obs(dt.date(y,11,11)),nth(y,11,3,4),obs(dt.date(y,12,25))}
    if y>=2021: h.add(obs(dt.date(y,6,19)))
    return h
H=set()
for y in range(2010,2027): H|=hol(y)
def bd(d): return d.weekday()<5 and d not in H
def deadline(h,strict=True):
    d=h;n=0
    while n<3:
        d+=dt.timedelta(1)
        if (bd(d) if strict else d.weekday()<5): n+=1
    return d
