    if y["s2"] and y["s1"] and y["s2"]<y["s1"]: flags.append("S2 before S1")
    for k in("s1","s2"):
        if y[k] and not bd(y[k]): flags.append(k+" on weekend/holiday "+y[k].strftime("%a"))
    if exact and y["s2"] and y["s2"]<r["hire"]: flags.append("S2 before hire")
    if flags: print(y["id"],y["name"],"hire",h,"exact" if exact else "",y["s1"],y["s2"],flags)
print(sorted(d for d in H if d.year in (2024,2017,2013)))
